INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q870947', 'Battle of Zhizhi', 'The Battle of Zhizhi (郅支之戰) was fought in 36 BC between the Han dynasty and the Xiongnu chieftain Zhizhi Chanyu. Zhizhi was defeated and killed.', -36, 10, NULL, -36, 12, NULL, 'month', 'October 36 BCE – December 36 BCE', 51, 'https://en.wikipedia.org/wiki/Battle_of_Zhizhi'),
  ('Q492415', 'Battle of Talas', 'The Battle of Talas (Chinese: 怛羅斯戰役; pinyin: Dáluósī Zhànyì; Arabic: معركة نهر طلاس, romanized: Maʿrakat nahr Ṭalās) was an armed confrontation between the Abbasid Caliphate along with the Tibetan Empire against the Tang dynasty and its allies in 751. In July of that year, the Tang and Abbasid armies clashed at the Talas River over control of the regions surrounding the Syr Darya.', 751, 5, NULL, 751, 9, NULL, 'month', 'May 751 – September 751', 73, 'https://en.wikipedia.org/wiki/Battle_of_Talas'),
  ('Q111943842', 'Otrar Catastrophe', 'The Otrar Catastrophe was a siege that took place between December 1219 and February 1220 during the Mongol invasion of the Khwarazmian Empire at Otrar, a large trading city on the Syr Darya river. Inalchuq, the city''s governor, had seized the goods of a Mongol trade caravan the previous year; after more provocations from Inalchuq''s liege and ruler of the Khwarazmian Empire, Shah Muhammad II, Genghis Khan launched a full-scale invasion of the empire.', 1219, 12, NULL, 1220, 2, NULL, 'month', 'December 1219 – February 1220', 47, 'https://en.wikipedia.org/wiki/Otrar_Catastrophe'),
  ('Q12823517', 'Battle of Ican', 'The Battle of Ican (Russian: Иканское сражение, romanized: Ikanskoye srazhenie), occurred on 16 December 1864 near Ikan as a part of the Russian conquest of Central Asia. In the battle, a Kokand army under the command of Alimqul was defeated by a cossack detachment.', 1864, 12, 16, 1864, 12, 18, 'day', '16 December 1864 – 18 December 1864', 34, 'https://en.wikipedia.org/wiki/Battle_of_Ican'),
  ('Q4219257', '1911 Kebin earthquake', 'The 1911 Kebin earthquake, or Chon-Kemin earthquake, struck Russian Turkestan on 3 January. Registering at a moment magnitude of 8.0, it killed 452 people, destroyed more than 770 buildings (which was almost all of the city) in Almaty, Kazakhstan, and resulted in 125 miles (201 km) of surface faulting in the valleys of Chon-Kemin, Chilik and Chon-Aksu.', 1911, 1, 3, NULL, NULL, NULL, 'day', '3 January 1911', 41, 'https://en.wikipedia.org/wiki/1911_Kebin_earthquake'),
  ('Q4142067', 'Kazakh famine of 1919–1922', 'The Kazakh famine of 1919–1922, also referred to as the Turkestan famine of 1919–1922, was a period of mass starvation and drought that took place in the Kirghiz ASSR (present-day Kazakhstan) and Turkestan ASSR as a result of the Russian Civil War, in which 400,000 to 750,000 peasants died. The event was part of the greater Russian famine of 1921–22 that affected other parts of what became the Soviet Union, in which up to 5,000,000 people died in total.', 1919, NULL, NULL, 1922, NULL, NULL, 'year', '1919–1922', 51, 'https://en.wikipedia.org/wiki/Kazakh_famine_of_1919%E2%80%931922'),
  ('Q1122110', 'Tajikistani Civil War', 'The Tajikistani Civil War was an armed conflict in Tajikistan that began in May 1992 and ended in June 1997. Regional groups from the Garm and Gorno-Badakhshan regions of Tajikistan rose up against the newly formed government of President Rahmon Nabiyev, which was dominated by people from the Khujand and Kulob regions.', 1992, 5, 5, 1997, 6, 27, 'day', '5 May 1992 – 27 June 1997', 72, 'https://en.wikipedia.org/wiki/Tajikistani_Civil_War'),
  ('Q4263317', 'Lisbon Protocol', 'The Lisbon Protocol to the 1991 Strategic Arms Reduction Treaty was a document signed by representatives of Belarus, Kazakhstan, Russia, and Ukraine that recognized the four states as successors of the Union of Soviet Socialist Republics and all of them assume obligations of the Soviet Union under the START I treaty. These were the four countries in which strategic nuclear weapons of the former Soviet Union remained.', 1992, 5, 23, NULL, NULL, NULL, 'day', '23 May 1992', 53, 'https://en.wikipedia.org/wiki/Lisbon_Protocol'),
  ('Q3661086', 'Kazakhstani presidential term referendum', 'A referendum on extending the presidential term of Nursultan Nazarbayev was held in Kazakhstan on 29 April 1995. Voters were asked "Do you agree to prolong the term of office of the President of the Republic of Kazakhstan Nursultan Nazarbayev, publicly elected on 1 December 1991, until 1 December 2000?" The question was approved by 95.5% of voters, with turnout reported to be 91.2%.', 1995, 4, 29, NULL, NULL, NULL, 'day', '29 April 1995', 34, 'https://en.wikipedia.org/wiki/1995_Kazakh_presidential_term_referendum'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q1571840', 'Kyzyl-Agash Dam failure', 'The Kyzyl-Agash Dam failure (Kazakh: Qyzylaǵash oqıǵasy), occurred in a dam located outside the village of Kyzyl-Agash, Jetisu Region, Kazakhstan. On 11 March 2010, the dam burst, flooding the village.', 2010, 3, 11, NULL, NULL, NULL, 'day', '11 March 2010', 39, 'https://en.wikipedia.org/wiki/Kyzyl-Agash_Dam_failure'),
  ('Q1087721', '2011 Zhanaozen riots', 'The Zhanaozen massacre (Kazakh: Жаңаөзен оқиғасы, romanized: Jañaözen oqiğasy) took place in Kazakhstan''s western Mangystau Region over the weekend of 16–17 December 2011. At least 14 protesters were killed by police in the oil town of Zhanaozen as they clashed with police on the country''s Independence Day, with unrest spreading to other towns in the oil-rich oblys, or region.', 2011, 12, 17, NULL, NULL, NULL, 'day', '17 December 2011', 53, 'https://en.wikipedia.org/wiki/Zhanaozen_massacre'),
  ('Q1704625', '2012 Kazakhstan Antonov An-72 crash', 'On 25 December 2012, an Antonov An-72 military transport aircraft operated by the Kazakh Armed Forces crashed about 20 km (12 mi) from the city of Shymkent, Kazakhstan, where the aircraft was preparing to land. All 27 people on board died in the crash.', 2012, 12, 25, NULL, NULL, NULL, 'day', '25 December 2012', 52, 'https://en.wikipedia.org/wiki/2012_Kazakhstan_Antonov_An-72_crash'),
  ('Q3866667', 'SCAT Airlines Flight 760', 'SCAT Airlines Flight 760 was a scheduled domestic passenger flight from Kokshetau to Almaty, Kazakhstan, operated by a Bombardier CRJ200 twinjet that on 29 January 2013 crashed in thick fog near the village of Kyzyltu, while on approach to Almaty. All 16 passengers and 5 crew on board were killed.', 2013, 1, 29, NULL, NULL, NULL, 'day', '29 January 2013', 55, 'https://en.wikipedia.org/wiki/SCAT_Airlines_Flight_760'),
  ('Q25052814', 'Sleep hollow', 'The sleeping sickness of Kalachi, Kazakhstan (with the place or the syndrome sometimes called sleepy hollow) is a conjectured medical condition which causes a person to sleep for days or weeks at a time, together with other symptoms such as hallucinations, nausea, intoxicated behavior, disorientation and memory loss. The phenomenon was only reported in Kalachi and the nearby village of Krasnogorsk.', 2013, 3, NULL, NULL, NULL, NULL, 'month', 'March 2013', 39, 'https://en.wikipedia.org/wiki/Sleeping_sickness_of_Kalachi%2C_Kazakhstan'),
  ('Q7453539', 'Bek Air Flight 2100', 'Bek Air Flight 2100 was a domestic passenger flight from Almaty to Nur-Sultan, Kazakhstan, operated by a Fokker 100 that crashed on 27 December 2019 while taking off from Almaty International Airport. Of the 98 people on board (93 passengers and 5 crew), 13 died in the crash and 66 were injured.', 2019, 12, 27, NULL, NULL, NULL, 'day', '27 December 2019', 65, 'https://en.wikipedia.org/wiki/Bek_Air_Flight_2100'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q110413718', '2022 Kazakh unrest', 'The 2022 Kazakh unrest, also known as January Events, Bloody January, or the January Tragedy, was a series of mass protests and civil unrest that began in Kazakhstan on 2 January 2022 after a sudden sharp increase in liquefied petroleum gas prices following the lifting of a government-enforced price cap on 1 January. The protests began peacefully in the oil-producing city of Zhanaozen and quickly spread to other cities in the country, especially the nation''s largest city, Almaty, which saw its demonstrations turn into violent riots, fueled by rising dissatisfaction with the government and…', 2022, NULL, NULL, 2022, 1, 11, 'year', '2022', 75, 'https://en.wikipedia.org/wiki/2022_Kazakh_unrest'),
  ('Q123253377', '2024 Kazakh nuclear power referendum', 'A referendum on the construction of the first nuclear power plant in Kazakhstan took place on 6 October 2024. The initiative was aimed at reducing fossil fuel reliance, curbing greenhouse gas emissions and bolstering national electricity generation in light of frequent power outages in recent years.', 2024, 10, 6, NULL, NULL, NULL, 'day', '6 October 2024', 39, 'https://en.wikipedia.org/wiki/2024_Kazakh_nuclear_power_referendum'),
  ('Q125360359', '2024 Central Asian floods', 'In April 2024, extensive flooding impacted several regions of Kazakhstan and Russia, specifically in the Ural Mountains and Siberia. Snow melt caused freshets resulting in the Orsk Dam collapsing.', 2024, 3, NULL, NULL, NULL, NULL, 'month', 'March 2024', 45, 'https://en.wikipedia.org/wiki/2024_Central_Asian_floods');
